class _FakePronunciationPlayback {
  final List<List<String>> playedSequences = [];
  var stopCount = 0;
  var throwOnPlay = false;

  Future<void> playPronunciationSequence(List<String> urls) async {
    if (throwOnPlay) {
      throw StateError('audio failed');
    }
    playedSequences.add(List<String>.of(urls));
  }

  Future<void> stopPronunciation() async {
    stopCount++;
  }
}

class _FakePronunciationRepository extends PronunciationRepository {
  _FakePronunciationRepository()
    : super(SupabaseClient('https://example.supabase.co', 'anon-key'));

  BookPronunciationManifest? manifest;
  final List<String> requestedBookIds = [];
  var throwOnLookup = false;

  @override
  Future<BookPronunciationManifest?> getManifestForBook(String bookId) async {
    requestedBookIds.add(bookId);
    if (throwOnLookup) {
      throw StateError('manifest failed');
    }
    return manifest;
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

import 'package:storia_kids/src/data/models.dart';
import 'package:storia_kids/src/features/reader/overlay/overlay_frame.dart';
import 'package:storia_kids/src/features/reader/overlay/overlay_layout_engine.dart';
import 'package:storia_kids/src/features/reader/overlay/overlay_text_element.dart';
import 'package:storia_kids/src/features/reader/overlay/text_overlay_utils.dart';
import 'package:storia_kids/src/features/reader/pronunciation_highlight.dart';

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  debugUseSystemFontsForOverlay = true;
  group('Overlay syllable pronunciation highlighting', () {
    test('layout attaches pronunciation parts only to the tapped word', () {
      const parts = [
        PronunciationHighlightPart(text: 'ba', startMs: 0, endMs: 650),
        PronunciationHighlightPart(text: 'na', startMs: 650, endMs: 1300),
        PronunciationHighlightPart(text: 'na', startMs: 1300, endMs: 1950),
      ];

      final frame = const OverlayLayoutEngineImpl().build(
        overlay: const TextOverlayConfig(
          version: 1,
          elements: [
            TextElement(
              id: 'line-1',
              text: 'Tap banana now',
              x: 0,
              y: 0,
              width: 100,
              fontFamily: 'Inter',
              fontSize: 10,
              fontWeight: 400,
              color: '#111111',
              textAlign: 'left',
              rotation: 0,
            ),
          ],
        ),
        imageSize: const Size(300, 200),
        activeWordIndex: -1,
        spokenWordIndices: const {},
        isActive: true,
        tappedWordIndex: 1,
        tappedWordHighlightParts: parts,
        activeTappedWordHighlightPartIndex: 2,
      );

      final wordTokens = frame.elements.single.tokens
          .where((token) => token.isWord)
          .toList(growable: false);

      expect(wordTokens.map((token) => token.raw), ['Tap', 'banana', 'now']);
      expect(wordTokens[0].pronunciationHighlightParts, isEmpty);
      expect(wordTokens[1].pronunciationHighlightParts, same(parts));
      expect(wordTokens[1].activePronunciationHighlightPartIndex, 2);
      expect(wordTokens[1].style.backgroundColor, isNull);
      expect(wordTokens[2].pronunciationHighlightParts, isEmpty);
    });

    testWidgets(
      'widget renders active syllable span and preserves tap callback',
      (tester) async {
        final taps = <({String word, int index})>[];
        final element = _elementFrame(
          raw: 'banana',
          parts: const [
            PronunciationHighlightPart(text: 'ba'),
            PronunciationHighlightPart(text: 'na'),
            PronunciationHighlightPart(text: 'na'),
          ],
          activeIndex: 1,
        );

        await tester.pumpWidget(
          MaterialApp(
            home: Scaffold(
              body: Stack(
                children: [
                  OverlayTextElement(
                    element: element,
                    isActive: true,
                    onWordTap: (word, index) =>
                        taps.add((word: word, index: index)),
                  ),
                ],
              ),
            ),
          ),
        );
        await tester.pump();

        final activeNaSpans = _textSpansWithText('na')
            .where((span) {
              return span.style?.backgroundColor ==
                      const Color.fromRGBO(139, 92, 246, 0.9) &&
                  span.style?.color == Colors.white &&
                  span.style?.fontWeight == FontWeight.w900;
            })
            .toList(growable: false);
        final inactiveSpans = _textSpansWithText('ba')
            .where((span) {
              return span.style?.backgroundColor ==
                  const Color.fromRGBO(139, 92, 246, 0.22);
            })
            .toList(growable: false);

        expect(activeNaSpans, hasLength(1));
        expect(inactiveSpans, hasLength(1));

        await tester.tap(find.byType(GestureDetector));
        expect(taps, [(word: 'banana', index: 4)]);
      },
    );

    testWidgets(
      'widget falls back to whole-word highlight when parts mismatch',
      (tester) async {
        final element = _elementFrame(
          raw: 'whale',
          parts: const [
            PronunciationHighlightPart(text: 'not'),
            PronunciationHighlightPart(text: 'matching'),
          ],
          activeIndex: 0,
        );

        await tester.pumpWidget(
          MaterialApp(
            home: Scaffold(
              body: Stack(
                children: [
                  OverlayTextElement(
                    element: element,
                    isActive: true,
                    onWordTap: (_, _) {},
                  ),
                ],
              ),
            ),
          ),
        );
        await tester.pump();

        final fallbackText = tester.widget<Text>(find.text('whale'));
        expect(
          fallbackText.style?.backgroundColor,
          const Color.fromRGBO(139, 92, 246, 0.85),
        );
      },
    );
  });
}

OverlayElementFrame _elementFrame({
  required String raw,
  required List<PronunciationHighlightPart> parts,
  required int? activeIndex,
}) {
  const style = TextStyle(color: Colors.black, fontSize: 24);
  return OverlayElementFrame(
    left: 0,
    top: 0,
    width: 300,
    textAlign: TextAlign.left,
    rotationRadians: 0,
    baseStyle: style,
    tokens: [
      OverlayTokenFrame(
        raw: raw,
        isWord: true,
        style: style.copyWith(color: Colors.white),
        globalWordIndex: 4,
        isTapped: true,
        pronunciationHighlightParts: parts,
        activePronunciationHighlightPartIndex: activeIndex,
      ),
    ],
    index: 0,
  );
}

List<TextSpan> _textSpansWithText(String text) {
  final spans = <TextSpan>[];
  final binding = TestWidgetsFlutterBinding.instance;
  final elements = binding.rootElement == null
      ? const <Element>[]
      : collectAllElementsFrom(binding.rootElement!, skipOffstage: false);

  for (final element in elements) {
    final widget = element.widget;
    if (widget is RichText) {
      _visitTextSpans(widget.text, (span) {
        if (span.text == text) {
          spans.add(span);
        }
      });
    }
  }
  return spans;
}

void _visitTextSpans(InlineSpan span, void Function(TextSpan span) visitor) {
  if (span is! TextSpan) {
    return;
  }
  visitor(span);
  for (final child in span.children ?? const <InlineSpan>[]) {
    _visitTextSpans(child, visitor);
  }
}

import 'package:cue/cue.dart';
import 'package:flutter/material.dart';

import 'overlay_frame.dart';

/// Per-element word-stagger entrance (Feature 4).
///
/// When a page becomes active and this element mounts (virtualization window
/// brings it into the tree), each word rises + fades in with a short stagger
/// derived from its token index within the element. The stagger is
/// entrance-only: once played, TTS word-highlight styling drives appearance.
class OverlayTextElement extends StatelessWidget {
  final OverlayElementFrame element;
  final bool isActive;
  final void Function(String word, int globalIndex)? onWordTap;
  final void Function(String word, int globalIndex)? onWordLongPress;

  const OverlayTextElement({
    super.key,
    required this.element,
    required this.isActive,
    this.onWordTap,
    this.onWordLongPress,
  });

  @override
  Widget build(BuildContext context) {
    final content = RichText(
      textAlign: element.textAlign,
      text: TextSpan(
        style: element.baseStyle,
        children: _buildSpans(element.tokens),
      ),
    );

    Widget decorated = content;
    final background = element.background;
    if (background != null) {
      decorated = Container(
        padding: EdgeInsets.all(background.padding),
        decoration: BoxDecoration(
          color: background.color,
          borderRadius: BorderRadius.circular(background.borderRadius),
        ),
        child: decorated,
      );
    }

    final rotated = element.rotationRadians != 0
        ? Transform.rotate(angle: element.rotationRadians, child: decorated)
        : decorated;

    // Stagger: element index drives base delay. Cue.onToggle plays forward
    // when this page becomes active and reverses when it leaves. Adjacent
    // pages in the virtualization window stay hidden at progress 0 until they
    // become active, matching the old flutter_animate behavior.
    final delayMs = 180 + element.index * 40;

    return Positioned(
      left: element.left,
      top: element.top,
      width: element.width,
      child: Cue.onToggle(
        toggled: isActive,
        motion: .smooth(),
        child: Actor(
          delay: Duration(milliseconds: delayMs),
          acts: const [OpacityAct.fadeIn(), SlideAct.y(from: 0.12)],
          child: rotated,
        ),
      ),
    );
  }

  List<InlineSpan> _buildSpans(List<OverlayTokenFrame> tokens) {
    final spans = <InlineSpan>[];

    for (final token in tokens) {
      if (!token.isWord) {
        spans.add(TextSpan(text: token.raw, style: token.style));
        continue;
      }

      final index = token.globalWordIndex;
      if (onWordTap != null && index != null) {
        Widget wordWidget = token.pronunciationHighlightParts.isNotEmpty
            ? _PronunciationWordText(token: token)
            : Text(token.raw, style: token.style);
        if (token.isTapped) {
          wordWidget = AnimatedScale(
            scale: 1.15,
            duration: const Duration(milliseconds: 200),
            curve: Curves.easeOutBack,
            child: wordWidget,
          );
        }
        spans.add(
          WidgetSpan(
            alignment: PlaceholderAlignment.baseline,
            baseline: TextBaseline.alphabetic,
            child: GestureDetector(
              behavior: HitTestBehavior.opaque,
              onTap: () => onWordTap?.call(token.raw, index),
              onLongPress: () => onWordLongPress?.call(token.raw, index),
              child: wordWidget,
            ),
          ),
        );
      } else {
        spans.add(TextSpan(text: token.raw, style: token.style));
      }
    }

    return spans;
  }
}

class _PronunciationWordText extends StatelessWidget {
  const _PronunciationWordText({required this.token});

  final OverlayTokenFrame token;

  static const Color _activePartBackground = Color.fromRGBO(139, 92, 246, 0.9);
  static const Color _inactivePartBackground = Color.fromRGBO(
    139,
    92,
    246,
    0.22,
  );
  static const Color _fallbackWordBackground = Color.fromRGBO(
    139,
    92,
    246,
    0.85,
  );

  @override
  Widget build(BuildContext context) {
    final spans = _buildSegmentSpans();
    if (spans == null) {
      return Text(
        token.raw,
        style: token.style.copyWith(backgroundColor: _fallbackWordBackground),
      );
    }

    return RichText(
      text: TextSpan(style: token.style, children: spans),
      textScaler: MediaQuery.textScalerOf(context),
    );
  }

  List<InlineSpan>? _buildSegmentSpans() {
    final raw = token.raw;
    final lowerRaw = raw.toLowerCase();
    final parts = token.pronunciationHighlightParts;
    var cursor = 0;
    final spans = <InlineSpan>[];

    for (var i = 0; i < parts.length; i++) {
      final partText = parts[i].text.trim();
      if (partText.isEmpty) {
        continue;
      }
      final matchIndex = lowerRaw.indexOf(partText.toLowerCase(), cursor);
      if (matchIndex < 0) {
        return null;
      }
      if (matchIndex > cursor) {
        spans.add(TextSpan(text: raw.substring(cursor, matchIndex)));
      }
      final end = matchIndex + partText.length;
      final isActive = i == token.activePronunciationHighlightPartIndex;
      spans.add(
        TextSpan(
          text: raw.substring(matchIndex, end),
          style: token.style.copyWith(
            backgroundColor: isActive
                ? _activePartBackground
                : _inactivePartBackground,
            color: isActive ? Colors.white : token.style.color,
            fontWeight: isActive ? FontWeight.w900 : token.style.fontWeight,
          ),
        ),
      );
      cursor = end;
    }

    if (cursor < raw.length) {
      spans.add(TextSpan(text: raw.substring(cursor)));
    }
    return spans.isEmpty ? null : spans;
  }
}

